package cache

import (
	"fmt"
	"sync"
	"testing"
	"time"
)

func TestZeroValueCache(t *testing.T) {
	var c Cache

	if v, ok := c.Get("missing"); ok || v != nil {
		t.Fatalf("zero-value Get(missing) = (%v, %v), want (nil, false)", v, ok)
	}

	c.Set("key", "value", time.Minute)
	if v, ok := c.Get("key"); !ok || v != "value" {
		t.Fatalf("Get(key) = (%v, %v), want (value, true)", v, ok)
	}

	c.Delete("key")
	if v, ok := c.Get("key"); ok || v != nil {
		t.Fatalf("Get after Delete = (%v, %v), want (nil, false)", v, ok)
	}
}

func TestMissingAndEmptyKey(t *testing.T) {
	c := new(Cache)

	if v, ok := c.Get("missing"); ok || v != nil {
		t.Fatalf("Get(missing) = (%v, %v), want (nil, false)", v, ok)
	}

	c.Set("", "empty-key", time.Minute)
	if v, ok := c.Get(""); !ok || v != "empty-key" {
		t.Fatalf("Get(empty key) = (%v, %v), want (empty-key, true)", v, ok)
	}

	c.Delete("")
	if v, ok := c.Get(""); ok || v != nil {
		t.Fatalf("Get(empty key) after Delete = (%v, %v), want (nil, false)", v, ok)
	}

	c.Delete("")
	c.Delete("never-existed")
}

func TestNilValueIsAHit(t *testing.T) {
	c := new(Cache)
	c.Set("nil-key", nil, time.Minute)

	v, ok := c.Get("nil-key")
	if !ok {
		t.Fatal("Get(nil-key) reported a miss, want a hit")
	}
	if v != nil {
		t.Fatalf("Get(nil-key) = %v, want nil", v)
	}

	if v, ok := c.Get("missing"); ok || v != nil {
		t.Fatalf("Get(missing) = (%v, %v), want (nil, false)", v, ok)
	}
}

func TestSetOverwritesValueAndTTL(t *testing.T) {
	c := new(Cache)

	c.Set("value-key", "first", time.Hour)
	c.Set("value-key", "second", time.Hour)
	if v, ok := c.Get("value-key"); !ok || v != "second" {
		t.Fatalf("Get(value-key) = (%v, %v), want (second, true)", v, ok)
	}

	c.Set("ttl-key", "old", time.Hour)
	c.Set("ttl-key", "new", 50*time.Millisecond)
	time.Sleep(100 * time.Millisecond)
	if v, ok := c.Get("ttl-key"); ok || v != nil {
		t.Fatalf("Get(ttl-key) after TTL reset = (%v, %v), want (nil, false)", v, ok)
	}
}

func TestNonPositiveTTLExpiresImmediately(t *testing.T) {
	c := new(Cache)

	c.Set("zero", "old", time.Hour)
	c.Set("zero", "new", 0)
	if v, ok := c.Get("zero"); ok || v != nil {
		t.Fatalf("Get(zero) after ttl=0 = (%v, %v), want (nil, false)", v, ok)
	}

	c.Set("negative", "old", time.Hour)
	c.Set("negative", "new", -time.Nanosecond)
	if v, ok := c.Get("negative"); ok || v != nil {
		t.Fatalf("Get(negative) after ttl<0 = (%v, %v), want (nil, false)", v, ok)
	}

	c.Set("absent-zero", "value", 0)
	if v, ok := c.Get("absent-zero"); ok || v != nil {
		t.Fatalf("Get(absent-zero) = (%v, %v), want (nil, false)", v, ok)
	}

	c.Set("absent-negative", "value", -time.Hour)
	if v, ok := c.Get("absent-negative"); ok || v != nil {
		t.Fatalf("Get(absent-negative) = (%v, %v), want (nil, false)", v, ok)
	}

	c.Set("zero", "valid", time.Minute)
	if v, ok := c.Get("zero"); !ok || v != "valid" {
		t.Fatalf("Get(zero) after valid Set = (%v, %v), want (valid, true)", v, ok)
	}
}

func TestExpiryHidesValue(t *testing.T) {
	c := new(Cache)
	c.Set("expiring", "value", 200*time.Millisecond)

	if v, ok := c.Get("expiring"); !ok || v != "value" {
		t.Fatalf("Get(expiring) before expiry = (%v, %v), want (value, true)", v, ok)
	}

	time.Sleep(300 * time.Millisecond)

	if v, ok := c.Get("expiring"); ok || v != nil {
		t.Fatalf("Get(expiring) after expiry = (%v, %v), want (nil, false)", v, ok)
	}
}

func TestIsExpiredBoundary(t *testing.T) {
	c := new(Cache)
	expiresAt := time.Now()
	e := entry{val: "value", expiresAt: expiresAt}

	if c.isExpired(e, expiresAt.Add(-time.Nanosecond)) {
		t.Fatal("entry is expired before expiresAt, want valid")
	}
	if !c.isExpired(e, expiresAt) {
		t.Fatal("entry at expiresAt is valid, want expired")
	}
	if !c.isExpired(e, expiresAt.Add(time.Nanosecond)) {
		t.Fatal("entry after expiresAt is valid, want expired")
	}
}

func TestConcurrentZeroValueInitialization(t *testing.T) {
	var c Cache
	const (
		goroutines   = 16
		perGoroutine = 50
	)

	start := make(chan struct{})
	var wg sync.WaitGroup
	wg.Add(goroutines)
	for i := 0; i < goroutines; i++ {
		go func(i int) {
			defer wg.Done()
			<-start
			for j := 0; j < perGoroutine; j++ {
				c.Set(fmt.Sprintf("g%d-k%d", i, j), j, time.Minute)
			}
		}(i)
	}

	close(start)
	wg.Wait()

	for i := 0; i < goroutines; i++ {
		for j := 0; j < perGoroutine; j++ {
			key := fmt.Sprintf("g%d-k%d", i, j)
			v, ok := c.Get(key)
			if !ok {
				t.Fatalf("Get(%s) missed after concurrent Set", key)
			}
			if v != j {
				t.Fatalf("Get(%s) = %v, want %d", key, v, j)
			}
		}
	}
}

func TestConcurrentSetGetDelete(t *testing.T) {
	c := new(Cache)
	c.Set("shared", "initial", time.Minute)

	const (
		goroutines = 8
		iterations = 200
	)

	start := make(chan struct{})
	var wg sync.WaitGroup
	wg.Add(goroutines)
	for i := 0; i < goroutines; i++ {
		go func(i int) {
			defer wg.Done()
			<-start
			for n := 0; n < iterations; n++ {
				key := fmt.Sprintf("k%d-%d", i, n%10)
				switch n % 3 {
				case 0:
					c.Set(key, n, time.Minute)
				case 1:
					c.Get(key)
				case 2:
					c.Delete(key)
				}
				c.Set("shared", i, time.Minute)
				c.Get("shared")
			}
		}(i)
	}

	close(start)
	wg.Wait()

	c.Set("final", "done", time.Minute)
	if v, ok := c.Get("final"); !ok || v != "done" {
		t.Fatalf("Get(final) = (%v, %v), want (done, true)", v, ok)
	}
	if _, ok := c.Get("shared"); !ok {
		t.Fatal("Get(shared) missed, want hit")
	}
}

// Package cache provides a concurrency-safe in-memory key/value cache whose
// entries expire after a configurable time-to-live.
package cache

import (
	"sync"
	"time"
)

// entry is a value together with the instant at which it stops being visible.
type entry struct {
	val       any
	expiresAt time.Time
}

// Cache is a concurrency-safe in-memory cache. Its zero value is ready to use.
//
// A Cache must not be copied after first use.
type Cache struct {
	mu    sync.RWMutex
	items map[string]entry
}

// Set stores val under key and replaces any previous value. A positive ttl is
// measured from this call; a ttl less than or equal to zero removes key
// immediately so that any previous value is no longer visible.
func (c *Cache) Set(key string, val any, ttl time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if ttl <= 0 {
		delete(c.items, key)
		return
	}
	if c.items == nil {
		c.items = make(map[string]entry)
	}
	c.items[key] = entry{
		val:       val,
		expiresAt: time.Now().Add(ttl),
	}
}

// Get returns the value stored under key and whether it is currently visible.
// Missing and expired entries return (nil, false); a visible nil value returns
// (nil, true). Expired entries are hidden without being removed from the map.
func (c *Cache) Get(key string) (any, bool) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	e, ok := c.items[key]
	if !ok {
		return nil, false
	}
	if c.isExpired(e, time.Now()) {
		return nil, false
	}
	return e.val, true
}

// Delete removes key. Deleting a missing key is a no-op and is safe to repeat.
func (c *Cache) Delete(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()

	delete(c.items, key)
}

// isExpired reports whether e is expired at now. An entry is expired once the
// current instant reaches or passes its expiry instant.
func (c *Cache) isExpired(e entry, now time.Time) bool {
	return !now.Before(e.expiresAt)
}
